def apply_migration(plan, check, begin, verify, commit, abort):
    if not check(plan):
        raise RuntimeError('precheck failed')
    begin(plan)
    if not verify(plan):
        abort(plan)
        raise RuntimeError('verification failed')
    commit(plan)
